operations.reducer:
const i = action.input;
if (i.name !== undefined) state.name = i.name;
if (i.kind !== undefined && i.kind !== null) state.kind = i.kind;
if (i.email !== undefined) state.email = i.email;
if (i.phone !== undefined) state.phone = i.phone;
if (i.website !== undefined) state.website = i.website;
if (i.vatId !== undefined) state.vatId = i.vatId;
if (i.registrationNumber !== undefined)
  state.registrationNumber = i.registrationNumber;
if (i.notes !== undefined) state.notes = i.notes;

operations.schema:
input SetAddressInput {
  street: String
  postalCode: String
  city: String
  country: String
}

operations.reducer:
state.address = {
  street: action.input.street ?? null,
  postalCode: action.input.postalCode ?? null,
  city: action.input.city ?? null,
  country: action.input.country ?? null,
};

const tag = action.input.tag.trim();
if (tag.length === 0) throw new InvalidTagError("A tag needs text");
if (state.tags.includes(tag))
  throw new DuplicateTagError(`Tag ${tag} exists`);
state.tags.push(tag);

const index = state.tags.indexOf(action.input.tag);
if (index === -1)
  throw new TagNotFoundError(`Tag ${action.input.tag} not found`);
state.tags.splice(index, 1);

state.people.push({
  id: action.input.id,
  name: action.input.name,
  role: orNone(action.input.role),
  email: orNone(action.input.email),
  phone: orNone(action.input.phone),
});

const person = state.people.find((p) => p.id === action.input.id);
if (!person)
  throw new PersonNotFoundError(`Person ${action.input.id} not found`);
if (action.input.name !== undefined && action.input.name !== null)
  person.name = action.input.name;
if (action.input.role !== undefined)
  person.role = orNone(action.input.role);
if (action.input.email !== undefined)
  person.email = orNone(action.input.email);
if (action.input.phone !== undefined)
  person.phone = orNone(action.input.phone);

const index = state.people.findIndex((p) => p.id === action.input.id);
if (index === -1)
  throw new PersonNotFoundError(`Person ${action.input.id} not found`);
state.people.splice(index, 1);

const next = action.input.archived ? "ARCHIVED" : "ACTIVE";
if (state.status === next)
  throw new StatusUnchangedError(
    `The contact is already ${next.toLowerCase()}`,
  );
state.status = next;
